bool ManualPunchBridge::acknowledgement(ManualPunchReceipt &r) noexcept {
    auto &s = *state_;
    if (!s.replies.tryPop(r))
        return false;
    --s.outstanding;
    if (r.command.action == ManualPunchAction::In) {
        auto *take = s.find(r.command.take);
        if (!take || !take->state_->pendingStarts)
            std::terminate();
